<?php
require_once __DIR__ . '/../../include/auth_admin.php';
$role='Admin';$area='admin';$activeMenu='arsip';$pageTitle='Detail Arsip Surat';$id=max(0,(int)($_GET['id']??0));
$stmt=$conn->prepare("SELECT a.id AS archive_id,a.tahun_arsip,a.lokasi_arsip,a.keterangan AS keterangan_arsip,a.archived_at, u.nama AS pengarsip, s.* FROM arsip_surat a JOIN surat s ON s.id=a.surat_id JOIN users u ON u.id=a.archived_by WHERE s.id=? AND s.status='Selesai' LIMIT 1");$stmt->bind_param('i',$id);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();$stmt->close();
if(!$row){$_SESSION['flash']=['type'=>'error','message'=>'Data arsip tidak ditemukan.'];header('Location: '.BASE_URL.'/'.$area.'/arsip_surat/index.php');exit;}
$logsStmt=$conn->prepare('SELECT l.*,u.nama AS pengubah FROM surat_status_logs l JOIN users u ON u.id=l.changed_by WHERE l.surat_id=? ORDER BY l.changed_at DESC,l.id DESC');$logsStmt->bind_param('i',$id);$logsStmt->execute();$logs=$logsStmt->get_result();
require __DIR__ . '/../../include/header.php';
?>
<div class="page-heading"><div><h1>Detail Arsip Surat</h1><p>Informasi arsip digital dan riwayat surat yang telah selesai.</p><div class="breadcrumbs"><a href="<?= BASE_URL ?>/<?= $area ?>/dashboard.php">Dashboard</a><span>›</span><a href="<?= BASE_URL ?>/<?= $area ?>/arsip_surat/index.php">Arsip Surat</a><span>›</span>Detail</div></div><a class="button button-light" href="<?= BASE_URL ?>/<?= $area ?>/status_surat/detail.php?id=<?= $id ?>">Lihat Riwayat Status</a></div>
<div class="archive-layout"><section class="panel"><div class="panel-heading"><div><h2><?= htmlspecialchars($row['nomor_surat'],ENT_QUOTES,'UTF-8') ?></h2><p><?= htmlspecialchars($row['perihal'],ENT_QUOTES,'UTF-8') ?></p></div><span class="status-badge status-done">Selesai · Diarsipkan</span></div><dl class="detail-list"><div><dt>Jenis Surat</dt><dd><?= $row['jenis_surat']==='Masuk'?'Surat Masuk':'Surat Keluar' ?></dd></div><div><dt>Nomor Surat</dt><dd><?= htmlspecialchars($row['nomor_surat'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Tanggal Surat</dt><dd><?= date('d-m-Y',strtotime($row['tanggal_surat'])) ?></dd></div><div><dt>Tahun Arsip</dt><dd><?= (int)$row['tahun_arsip'] ?></dd></div><div><dt>Pengirim</dt><dd><?= htmlspecialchars($row['pengirim']?:'-',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Tujuan</dt><dd><?= htmlspecialchars($row['tujuan']?:'-',ENT_QUOTES,'UTF-8') ?></dd></div><div class="full-span"><dt>Perihal</dt><dd><?= htmlspecialchars($row['perihal'],ENT_QUOTES,'UTF-8') ?></dd></div><div class="full-span"><dt>Keterangan Surat</dt><dd><?= nl2br(htmlspecialchars($row['deskripsi']?:'-',ENT_QUOTES,'UTF-8')) ?></dd></div></dl><?php if(!empty($row['uploaded_file'])): ?><div class="file-card"><span class="file-symbol">FILE</span><div><strong>Lampiran surat</strong><small>Disimpan sebagai lampiran digital</small></div><div class="file-actions"><a class="button button-light" href="<?= BASE_URL ?>/proses/file_surat.php?id=<?= $id ?>&mode=view">Lihat</a><a class="button button-dark" href="<?= BASE_URL ?>/proses/file_surat.php?id=<?= $id ?>&mode=download">Unduh</a></div></div><?php endif; ?></section>
<aside class="panel archive-detail"><div class="panel-heading"><div><h2>Informasi Pengarsipan</h2><p>Metadata penyimpanan arsip.</p></div></div><dl class="compact-detail"><div><dt>Lokasi</dt><dd><?= htmlspecialchars($row['lokasi_arsip'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Tahun Arsip</dt><dd><?= (int)$row['tahun_arsip'] ?></dd></div><div><dt>Tanggal Arsip</dt><dd><?= date('d-m-Y H:i',strtotime($row['archived_at'])) ?></dd></div><div><dt>Diarsipkan oleh</dt><dd><?= htmlspecialchars($row['pengarsip'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Keterangan Arsip</dt><dd><?= htmlspecialchars($row['keterangan_arsip']?:'-',ENT_QUOTES,'UTF-8') ?></dd></div></dl><hr class="section-rule"><h3 class="subheading">Riwayat Terakhir</h3><?php if($logs->num_rows>0): ?><div class="timeline compact-timeline"><?php while($log=$logs->fetch_assoc()): ?><div class="timeline-item"><span class="timeline-dot"></span><div class="timeline-content"><div class="timeline-meta"><strong><?= htmlspecialchars($log['status_baru'],ENT_QUOTES,'UTF-8') ?></strong><time><?= date('d-m-Y H:i',strtotime($log['changed_at'])) ?></time></div><?php if($log['catatan']): ?><p><?= htmlspecialchars($log['catatan'],ENT_QUOTES,'UTF-8') ?></p><?php endif; ?><small><?= htmlspecialchars($log['pengubah'],ENT_QUOTES,'UTF-8') ?></small></div></div><?php endwhile; ?></div><?php else: ?><div class="empty-state">Riwayat belum tersedia.</div><?php endif; ?></aside></div>
<?php require __DIR__ . '/../../include/footer.php'; ?>
